"""Nonblocking playback-error alerts and bounded playlist recovery."""
from __future__ import annotations
import base64
import ctypes
import os
from pathlib import Path
import subprocess
import sys
import threading
import time

# CC0 recording: https://commons.wikimedia.org/wiki/File:Wilhelm_Scream.ogg
WILHELM_OGG_B64 = """"""


def file_problem(path):
    """Return a concise reason for a selected path that cannot start playback."""
    path = Path(path)
    try:
        if not path.is_file():
            return 'missing'
        if path.stat().st_size == 0:
            return 'empty'
    except OSError as exc:
        return 'unreadable: ' + str(exc)
    return None


def next_playable_entry(order, current, on_missing=None):
    """Scan at most one queue revolution, never returning a known bad slot."""
    if not order:
        return None
    current = Path(current)
    try:
        index = next(i for i, item in enumerate(order) if Path(item) == current)
    except StopIteration:
        index = -1
    for offset in range(1, len(order) + 1):
        candidate = Path(order[(index + offset) % len(order)])
        if candidate == current: continue
        problem = file_problem(candidate)
        if problem is None: return candidate
        if problem == 'missing' and on_missing is not None: on_missing(candidate)
    return None


def record_missing_playlist_entries(alerts, paths, continuing):
    """Record every encountered missing playlist entry without interrupting playback."""
    silent = {'ErrorPopupEnabled': 0, 'ErrorWindowsNotificationEnabled': 0, 'ErrorSoundEnabled': 0}
    for path in paths:
        alerts.emit(path=path, reason='The playlist audio file is missing.', settings=silent,
                    continuing=continuing)


def _popup(title, message):
    if os.name != 'nt':
        return
    try:
        # A separate process keeps the dialog visible when the last bad
        # playlist entry makes PAFPlayer itself exit immediately afterward.
        script = ('import ctypes,sys;'
                  'ctypes.windll.user32.MessageBoxW('
                  'None,sys.argv[2],sys.argv[1],0x10|0x40000)')
        subprocess.Popen([sys.executable, '-c', script, title, message],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL,
                         creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
    except (OSError, ValueError):
        try:
            ctypes.windll.user32.MessageBoxW(None, message, title, 0x10 | 0x40000)
        except (AttributeError, OSError):
            pass


def _sound(ffplay_path):
    if not ffplay_path:
        return
    try:
        command = [str(ffplay_path), '-nodisp', '-autoexit', '-loglevel', 'error',
                   '-volume', '1', '-i', 'pipe:0']
        flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0)
        player = subprocess.Popen(command, stdin=subprocess.PIPE,
                                  stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                  creationflags=flags)
        try:
            player.communicate(base64.b64decode(WILHELM_OGG_B64), timeout=8)
        except subprocess.TimeoutExpired:
            player.kill()
            player.communicate()
    except (OSError, ValueError):
        pass


class ErrorAlerts:
    """At most one local popup/sound/notification for each error and file revision."""
    def __init__(self):
        self._seen = {}
        self._session_errors = []
        self._next_error_id = 1
        self._lock = threading.Lock()

    def snapshot(self):
        """Return newest-first, JSON-safe errors recorded during this process."""
        with self._lock:
            return [dict(item) for item in reversed(self._session_errors)]

    def mark_healthy(self, path):
        """Rearm alerts after a track has actually become playable again."""
        identity = os.path.normcase(str(Path(path).absolute()))
        with self._lock:
            self._seen.pop(identity, None)

    def emit(self, *, path, reason, settings, tray=None, ffplay_path=None,
             continuing=True):
        path = Path(path)
        try:
            stamp = (path.stat().st_size, path.stat().st_mtime_ns)
        except OSError:
            stamp = (None, None)
        identity = os.path.normcase(str(path.absolute()))
        signature = (str(reason), stamp)
        with self._lock:
            seen = self._seen.setdefault(identity, set())
            if signature in seen:
                return False
            seen.add(signature)
            outcome = ('Skipping to the next playable track.' if continuing
                       else 'No playable track remains in this request.')
            self._session_errors.append({
                'id': self._next_error_id,
                'epoch': time.time(),
                'path': str(path),
                'filename': path.name,
                'reason': str(reason),
                'outcome': outcome,
                'continuing': bool(continuing),
            })
            self._next_error_id += 1
            if len(self._session_errors) > 250:
                del self._session_errors[:-250]
        title = 'PAFPlayer could not play a track'
        message = f'{path.name}\n{reason}\n{outcome}'
        if settings.get('ErrorWindowsNotificationEnabled', 1) and tray is not None:
            try:
                tray.notify_error(title, message)
            except Exception:
                # Failure to reach the shell must never stop playlist recovery.
                pass
        if settings.get('ErrorPopupEnabled', 1):
            try:
                threading.Thread(target=_popup, args=(title, message),
                                 name='paf-error-popup', daemon=False).start()
            except (OSError, RuntimeError):
                pass
        if settings.get('ErrorSoundEnabled', 1):
            try:
                threading.Thread(target=_sound, args=(ffplay_path,),
                                 name='paf-error-sound', daemon=False).start()
            except (OSError, RuntimeError):
                pass
        return True
